   [145]={next_id=146, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="或许是这个小女孩的做法启发了这些不知道该如何感谢你们的沙漠居民，陆陆续续有人离去，过不了一会儿又会回到这儿，手里会多一些东西。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT206_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [146]={next_id=147, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="本着某种公平的原则——你是这么猜测克里安卡的心态的，她没有拒绝任何一个人的礼物。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT206_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
